args.query:
-- Count rows before
SELECT 'train_before' as which, COUNT(*) as cnt FROM train_set;
SELECT 'test_before' as which, COUNT(*) as cnt FROM test_set;

-- Insert all rows from test_set into train_set
INSERT INTO train_set
SELECT * FROM test_set;

-- Count rows after
SELECT 'train_after' as which, COUNT(*) as cnt FROM train_set;
SELECT 'test_after' as which, COUNT(*) as cnt FROM test_set;

-- Show schema for train_set
PRAGMA table_info('train_set');

-- Count total rows and distinct rows to detect exact duplicate records
SELECT COUNT(*) AS total_rows, COUNT(DISTINCT *) AS distinct_rows FROM train_set;

-- Create backups (timestamped)
CREATE TABLE IF NOT EXISTS train_set_backup AS SELECT * FROM train_set;
CREATE TABLE IF NOT EXISTS test_set_backup AS SELECT * FROM test_set;

-- Verify backups created
SELECT 'backup_train_count' as which, COUNT(*) as cnt FROM train_set_backup;
SELECT 'backup_test_count' as which, COUNT(*) as cnt FROM test_set_backup;

-- Count total and distinct (by concatenation) in train_set
SELECT COUNT(*) AS total_rows, COUNT(DISTINCT sample_id || '||' || COALESCE(sleep_hours,'') || '||' || COALESCE(caffeine_mg,'') || '||' || COALESCE(label,'')) AS distinct_rows FROM train_set;

-- Create backups (overwrite if exist: drop then create)
DROP TABLE IF EXISTS train_set_backup;
CREATE TABLE train_set_backup AS SELECT * FROM train_set;
DROP TABLE IF EXISTS test_set_backup;
CREATE TABLE test_set_backup AS SELECT * FROM test_set;

-- Verify backups created
SELECT 'backup_train_count' as which, COUNT(*) as cnt FROM train_set_backup;
SELECT 'backup_test_count' as which, COUNT(*) as cnt FROM test_set_backup;
